-- Minimal existing-project schema for executing the actual migrations in
-- PostgreSQL. auth/storage represent Supabase-owned schemas in production.
do $$ begin
  if not exists (select from pg_roles where rolname = 'anon') then create role anon nologin; end if;
  if not exists (select from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
end $$;
create schema auth;
create schema storage;
grant usage on schema public, auth, storage to anon, authenticated;
create table auth.users (id uuid primary key, email text);
create function auth.uid() returns uuid language sql stable as $$
  select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid;
$$;

create type public.orientation_status as enum ('Draft', 'Published', 'Open', 'Closed', 'Fully Booked');
create type public.reservation_status as enum ('Pending', 'Confirmed', 'Cancelled');
create table public.orientations (
  id bigint generated by default as identity primary key,
  title text not null default 'Test orientation',
  branch text not null default 'Tagum',
  venue text not null default 'Test venue',
  description text,
  date date not null,
  start_time text not null default '09:00 AM',
  end_time text not null default '12:00 PM',
  capacity integer not null default 2,
  reserved integer not null default 0,
  status public.orientation_status not null default 'Open',
  created_at timestamptz not null default now()
);
create table public.reservations (
  id bigint generated by default as identity primary key,
  orientation_id bigint not null references public.orientations(id) on delete cascade,
  reference_number varchar(50) not null unique,
  full_name text not null,
  phone text not null,
  email text not null,
  address text not null,
  city text not null,
  province text not null,
  notes text,
  status public.reservation_status not null default 'Pending',
  created_at timestamptz not null default now()
);
create table public.cms_programs (id bigint generated by default as identity primary key, title text, is_published boolean);
create table public.cms_branches (like public.cms_programs including all);
create table public.cms_gallery (like public.cms_programs including all);
create table public.cms_testimonials (like public.cms_programs including all);
create table public.cms_faqs (like public.cms_programs including all);
-- Exercise both a legacy numeric publication flag and a table with no flag.
create table public.cms_partners (id bigint generated by default as identity primary key, title text, is_published integer);
create table public.cms_stats (id bigint generated by default as identity primary key, title text);
create table public.site_settings (setting_key text primary key, setting_value text);

create table storage.objects (id uuid primary key default gen_random_uuid(), bucket_id text not null, name text not null);
alter table storage.objects enable row level security;
grant select, insert, update, delete on storage.objects to anon, authenticated;
create policy "Legacy permissive storage" on storage.objects for all to public using (true) with check (true);
grant usage, select on all sequences in schema public to authenticated;
